        await waitForElementToBeRemoved(() => screen.queryAllByLabelText("Loading..."));

        const ssoButton = container.querySelector(".mx_SSOButton");
        expect(ssoButton).toBeTruthy();
    });

    it("should handle serverConfig updates correctly", async () => {
